import { NgTemplateOutlet } from '@angular/common';
import { booleanAttribute, ChangeDetectionStrategy, Component, inject, input } from '@angular/core';
import { Params, RouterLink } from '@angular/router';
import { DropdownComponent } from '../dropdown/dropdown.component';

@Component({
	selector: 'espd-dropdown-item',
	templateUrl: './dropdown-item.component.html',
	styleUrls: ['./dropdown-item.component.scss'],
	changeDetection: ChangeDetectionStrategy.OnPush,
	host: { 'role': 'menuitem' },
	imports: [NgTemplateOutlet, RouterLink]
})
export class DropdownItemComponent {
	public active = input(false, { transform: booleanAttribute });
	public disabled = input(false, { transform: booleanAttribute });
	public routerPath = input<string>();
	public queryParams = input<Params | null>();
	public href = input<string>();
	public target = input<'blank' | 'self'>();

	private dropdownComponent = inject(DropdownComponent);

	public onClick(): void {
		this.dropdownComponent.onChildClick();
	}
}