/* eslint-disable @typescript-eslint/dot-notation */
import { Directive, ElementRef, HostListener, inject } from '@angular/core';
import { FocusableChildren } from 'espd-common/placeholder/api';
import { BsDropdownDirective } from 'ngx-bootstrap/dropdown';

const UP = 38;
const DOWN = 40;
const TAB = 9;

@Directive({
	selector: '[espdDropdown],[dropdown]',
	exportAs: 'dropdown-directive'
})
export class DropdownDirective implements FocusableChildren {

	private listItems: HTMLElement[] = [];
	private focusedIndex?: number;
	private hostShowFunction?: () => void;

	private element = inject<ElementRef<HTMLElement>>(ElementRef);
	private hostDropdown = inject(BsDropdownDirective, { host: true });

	constructor() {
		this.hostShowFunction = this.hostDropdown.show.bind(this.hostDropdown);
		this.hostDropdown.show = () => { this.show(); };
	}

	@HostListener('keydown', ['$event'])
	public handleKeyboardEvent(event: KeyboardEvent): boolean | undefined {
		if (this.hostDropdown) {
			if (event.keyCode === DOWN || (event.keyCode === TAB && this.hostDropdown.isOpen && !event.shiftKey && (this.focusedIndex === undefined || this.focusedIndex < this.listItems.length - 1))) {
				this.onPressDown();
				event.preventDefault();
				return false;
			} else if (event.keyCode === UP || (event.keyCode === TAB && this.hostDropdown.isOpen && event.shiftKey && this.focusedIndex !== undefined && this.focusedIndex > 0)) {
				this.onPressUp();
				event.preventDefault();
				return false;
			} else if (event.keyCode === TAB && this.hostDropdown.isOpen && event.shiftKey && this.focusedIndex === 0) {
				this.focusedIndex = undefined;
			}
		}
		return;
	}

	@HostListener('keyup.esc')
	public handleEscape(): void {
		if (this.hostDropdown['_state'].autoClose) {
			this.hostDropdown['_state'].toggleClick.emit(false);
		}
	}

	@HostListener('focusout')
	public focusout(): void {
		setTimeout(() => {
			if (this.hostDropdown && !this.isDescendant(this.element.nativeElement, document.activeElement)) {
				this.hostDropdown.hide();
			}
		}, 0);
	}

	public indexOf(item: HTMLElement): number {
		return this.listItems.indexOf(item);
	}

	public itemAt(index: number): HTMLElement {
		return this.listItems[index];
	}

	public focusOnIndex(index: number): void {
		index = index >= this.listItems.length ? this.listItems.length - 1 : index;

		this.itemAt(index)?.focus();
		this.focusedIndex = index;
	}

	private onPressDown(): void {
		if (!this.hostDropdown.isOpen) {
			this.show();
		} else {
			this.selectNextItem();
		}
	}

	private onPressUp(): void {
		if (this.hostDropdown.isOpen) {
			this.selectPreviousItem();
		}
	}

	private show(): void {
		this.hostShowFunction?.call(this.hostDropdown);
		this.focusedIndex = undefined;
		setTimeout(() => {
			this.listItems = Array.from(this.element.nativeElement.querySelectorAll<HTMLElement>('[role="menu"] a, [role="menu"] button'))
				.filter(e => this.elementIsVisible(e) && !e.hasAttribute('disabled') && !e.classList.contains('disabled'));
		}, 0);
	}

	private elementIsVisible(e: HTMLElement): boolean {
		return e.offsetParent !== null;
	}

	private selectNextItem(): void {
		if (this.focusedIndex == null) {
			this.focusedIndex = 0;
		} else {
			if (this.focusedIndex < this.listItems.length - 1) {
				this.focusedIndex++;
			} else {
				this.focusedIndex = 0;
			}
		}
		this.listItems[this.focusedIndex].focus();
	}

	private selectPreviousItem(): void {
		if (this.focusedIndex == null) {
			this.focusedIndex = 0;
		} else {
			if (this.focusedIndex > 0) {
				this.focusedIndex--;
			} else {
				this.focusedIndex = this.listItems.length - 1;
			}
		}
		this.listItems[this.focusedIndex].focus();
	}

	private isDescendant(parent: Element, child: Element | null): boolean {
		let node = child?.parentNode;
		while (node != null) {
			if (node === parent) {
				return true;
			}
			node = node.parentNode;
		}
		return false;
	}
}